package io.aetheris.orchestrator.memory;
import jakarta.transaction.Transactional;import org.springframework.stereotype.Service;import java.util.*;
@Service public class Stage9AdaptiveVectorIndexService {private static final String TOMBSTONE="stage9-tombstoned";private final MemoryVectorRepository vectors;private final KnowledgeNodeRepository nodes;private final SemanticMemoryService lexical;private final AdaptiveLocalEmbeddingAdapter embedding;public Stage9AdaptiveVectorIndexService(MemoryVectorRepository vectors,KnowledgeNodeRepository nodes,SemanticMemoryService lexical,AdaptiveLocalEmbeddingAdapter embedding){this.vectors=vectors;this.nodes=nodes;this.lexical=lexical;this.embedding=embedding;}@Transactional public MemoryVectorEntity index(UUID id){KnowledgeNodeEntity n=nodes.findById(id).orElseThrow(()->new NoSuchElementException("Unknown knowledge node: "+id));float[]v=embedding.embed(n.getMemoryKey()+"\n"+n.getContent()+"\n"+String.join(" ",n.getTags()));MemoryVectorEntity e=vectors.findByKnowledgeNodeIdAndAdapterId(id,embedding.id()).orElseGet(()->new MemoryVectorEntity(UUID.randomUUID(),id,embedding.id(),v));e.update(id,embedding.id(),v);return vectors.save(e);}@Transactional public int rebuild(){int c=0;for(KnowledgeNodeEntity n:nodes.findTop500ByOrderByUpdatedAtDesc()){if(n.getTags().contains(TOMBSTONE))continue;index(n.getId());c++;}return c;}public List<VectorMemorySearchResult> search(String q,MemoryScope scope,String ns,boolean protectedData,int limit){float[]query=embedding.embed(q);List<VectorMemorySearchResult>out=new ArrayList<>();for(MemoryVectorEntity v:vectors.findTop1000ByAdapterIdOrderByUpdatedAtDesc(embedding.id())){KnowledgeNodeEntity n=nodes.findById(v.getKnowledgeNodeId()).orElse(null);if(n==null||n.getTags().contains(TOMBSTONE)||(scope!=null&&n.getScope()!=scope)||(ns!=null&&!ns.isBlank()&&!n.getNamespace().equalsIgnoreCase(ns.trim()))||(!protectedData&&n.isProtectedData()))continue;double s=cos(query,v.vector());if(s>0)out.add(new VectorMemorySearchResult(n,s,"stage9 adaptive local vector cosine"));}out.sort(Comparator.comparingDouble(VectorMemorySearchResult::score).reversed());if(out.isEmpty())return lexical.search(q,scope,ns,protectedData,limit).stream().map(x->new VectorMemorySearchResult(x.node(),x.score(),"lexical fallback")).toList();return out.stream().limit(Math.max(1,Math.min(limit,50))).toList();}private double cos(float[]a,float[]b){int n=Math.min(a.length,b.length);double dot=0,aa=0,bb=0;for(int i=0;i<n;i++){dot+=a[i]*b[i];aa+=a[i]*a[i];bb+=b[i]*b[i];}return aa==0||bb==0?0:dot/(Math.sqrt(aa)*Math.sqrt(bb));}}
